Connect-AzAccount

$subscriptions = Get-AzSubscription

foreach ($subscription in $subscriptions) {
    Set-AzContext -SubscriptionId $subscription.Id | Out-Null
    Get-AzVM | Select-Object @{Name='SubscriptionName';Expression={$subscription.Name}}, ResourceGroupName, Name, Location
}

$vms = Get-AzVM -ResourceGroupName 'rg-prod' -Status | Where-Object { $_.PowerState -eq 'VM running' }

foreach ($vm in $vms) {
    Stop-AzVM -ResourceGroupName $vm.ResourceGroupName -Name $vm.Name -Force
}

# Requires PowerShell 5.1 and the Az module
$vaults = Get-AzKeyVault

foreach ($vault in $vaults) {
    Write-Output "Key Vault: $($vault.VaultName)"
    (Get-AzKeyVault -VaultName $vault.VaultName).AccessPolicies | Format-Table ObjectId, PermissionsToKeys, PermissionsToSecrets
}
